function svgToDataUrl(svg) {
  return `data:image/svg+xml;base64,${btoa(unescape(encodeURIComponent(svg)))}`;
}

// Превращает data URL SVG в raw PNG base64 (через canvas).
export function svgToPngBase64(svgString) {
  return new Promise((resolve, reject) => {
    const blob = new Blob([svgString], { type: "image/svg+xml" });
    const url = URL.createObjectURL(blob);
    const img = new Image();
    img.onload = () => {
      const c = document.createElement("canvas");
      c.width = c.height = 256;
      const ctx = c.getContext("2d");
      if (!ctx) { URL.revokeObjectURL(url); return reject("no ctx"); }
      ctx.drawImage(img, 0, 0, 256, 256);
      URL.revokeObjectURL(url);
      resolve(c.toDataURL("image/png").split(",")[1] || "");
    };
    img.onerror = () => { URL.revokeObjectURL(url); reject("svg fail"); };
    img.src = url;
  });
}

function imageFileToPngBase64(file) {
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      const canvas = document.createElement("canvas");
      canvas.width = canvas.height = 256;
      const ctx = canvas.getContext("2d");
      if (!ctx || !img.naturalWidth || !img.naturalHeight) {
        URL.revokeObjectURL(url);
        reject(new Error("image decode failed"));
        return;
      }

      const scale = Math.max(256 / img.naturalWidth, 256 / img.naturalHeight);
      const width = img.naturalWidth * scale;
      const height = img.naturalHeight * scale;
      ctx.drawImage(img, (256 - width) / 2, (256 - height) / 2, width, height);
      URL.revokeObjectURL(url);
      resolve(canvas.toDataURL("image/png").split(",")[1] || "");
    };
    img.onerror = () => {
      URL.revokeObjectURL(url);
      reject(new Error("image decode failed"));
    };
    img.src = url;
  });
}

// Превращает data URL SVG → raw PNG base64, data URL PNG → raw base64, или просто raw base64.
export function extractBase64(dataUrl) {
  if (!dataUrl) return "";
  if (dataUrl.includes(",")) return dataUrl.split(",")[1];
  return dataUrl;
}

export function getBuiltinIconDataUrl(id) {
  const icon = BUILTIN_ICONS.find((i) => i.id === id);
  return icon ? svgToDataUrl(icon.svg) : null;
}

export function getSvgForDataUrl(dataUrl) {
  const icon = BUILTIN_ICONS.find((i) => svgToDataUrl(i.svg) === dataUrl);
  return icon ? icon.svg : null;
}

// Определяет ID встроенной иконки по raw PNG base64 (через сравнение с предвычисленными хешами).
// Если не совпало — значит пользовательская иконка, возвращает null.
let _builtinPngCache = null;
async function getBuiltinIdByBase64(b64) {
  if (!b64) return null;
  if (!_builtinPngCache) {
    _builtinPngCache = {};
    for (const icon of BUILTIN_ICONS) {
      try {
        _builtinPngCache[icon.id] = await svgToPngBase64(icon.svg);
      } catch {}
    }
  }
  for (const [id, pngB64] of Object.entries(_builtinPngCache)) {
    if (pngB64 === b64) return id;
  }
  return null;
}

export default function InstanceIconPicker({ currentIconData, activeId: activeIdProp, onSelect, onUpload, compact }) {
  const ref = useRef(null);
  const size = compact ? "h-5 w-5" : "h-6 w-6";
  const cols = compact ? "grid-cols-5 min-[360px]:grid-cols-6 min-[420px]:grid-cols-8" : "grid-cols-6 min-[420px]:grid-cols-8 sm:grid-cols-10";
  const gap = compact ? "gap-px" : "gap-0.5";

  const handleFile = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      if (file.size > 5 * 1024 * 1024) return;
      const pngBase64 = await imageFileToPngBase64(file);
      if (pngBase64 && onUpload) onUpload(pngBase64);
    } catch {
      // Ignore files the browser cannot decode as images.
    } finally {
      e.target.value = "";
    }
  };

  return (
    <div>
      <p className="mb-px text-[9px] text-zinc-500 leading-none">Иконка</p>
      <div
        className={`launcher-scroll grid ${cols} ${gap} ${compact ? "max-h-[52px]" : "max-h-36"} overflow-y-auto pr-3 [scrollbar-gutter:stable]`}
      >
        {BUILTIN_ICONS.map((icon) => {
          const url = svgToDataUrl(icon.svg);
          return (
            <button
              key={icon.id}
              onClick={() => onSelect(url, icon.id)}
              title={icon.id}
              className={`${size} overflow-hidden rounded border transition ${
                activeIdProp === icon.id
                  ? "border-violet-400 shadow-[0_0_6px_rgba(139,92,246,0.4)]"
                  : "border-white/10 hover:border-white/30"
              }`}
            >
              <img src={url} alt="" className="h-full w-full object-cover" />
            </button>
          );
        })}
        <button
          onClick={() => ref.current?.click()}
          title="Загрузить свою"
          className={`${size} flex items-center justify-center rounded border border-dashed border-white/15 text-zinc-500 transition hover:border-white/30 hover:text-white`}
        >
          <Upload size={compact ? 8 : 10} />
        </button>
        {currentIconData && (
          <button
            onClick={() => onSelect(null)}
            title="Убрать"
            className={`${size} flex items-center justify-center rounded border border-dashed border-rose-500/30 text-rose-400 transition hover:border-rose-500/60 hover:text-rose-300`}
          >
            <X size={compact ? 8 : 10} />
          </button>
        )}
      </div>
      <input ref={ref} type="file" accept="image/png,image/jpeg,image/webp" className="hidden" onChange={handleFile} />
    </div>
  );
}
